window.ScripturaLexicons.BDAG_PART_0250 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0250-01\" data-source=\"BDAG\" data-search=\"ὁδός, οῦ, ἡ substantivo feminino caminho; estrada; viagem; modo de vida; o Caminho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁδός, οῦ, ἡ</td><td>substantivo feminino</td><td>caminho; estrada; viagem; modo de vida; o Caminho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0250-02\" data-source=\"BDAG\" data-search=\"ὀδούς, ὀδόντος, ὁ substantivo masculino dente; dentes BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀδούς, ὀδόντος, ὁ</td><td>substantivo masculino</td><td>dente; dentes</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0250-03\" data-source=\"BDAG\" data-search=\"ὀδυνάω verbo; na literatura, médio-passivo sentir dor; sofrer tormento; afligir-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀδυνάω</td><td>verbo; na literatura, médio-passivo</td><td>sentir dor; sofrer tormento; afligir-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0250-04\" data-source=\"BDAG\" data-search=\"ὀδύνη, ης, ἡ substantivo feminino dor física; sofrimento; angústia moral BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀδύνη, ης, ἡ</td><td>substantivo feminino</td><td>dor física; sofrimento; angústia moral</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0250-05\" data-source=\"BDAG\" data-search=\"ὀδύνω, οῦ, ὁ forma verbal de leitura variante sentir dor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀδύνω, οῦ, ὁ</td><td>forma verbal de leitura variante</td><td>sentir dor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0250-06\" data-source=\"BDAG\" data-search=\"ὀδυρμός, οῦ, ὁ substantivo masculino lamentação; pranto; luto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀδυρμός, οῦ, ὁ</td><td>substantivo masculino</td><td>lamentação; pranto; luto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0250-07\" data-source=\"BDAG\" data-search=\"ὀδύρομαι verbo médio depoente lamentar; prantear BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀδύρομαι</td><td>verbo médio depoente</td><td>lamentar; prantear</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0250-08\" data-source=\"BDAG\" data-search=\"Ὀζίας, ου, ὁ nome próprio masculino Uzias, rei hebreu BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ὀζίας, ου, ὁ</td><td>nome próprio masculino</td><td>Uzias, rei hebreu</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0250-09\" data-source=\"BDAG\" data-search=\"ὄζος, ου, ὁ substantivo masculino nó de galho; nodosidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄζος, ου, ὁ</td><td>substantivo masculino</td><td>nó de galho; nodosidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0250-10\" data-source=\"BDAG\" data-search=\"ὄζω verbo exalar cheiro; cheirar; feder BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄζω</td><td>verbo</td><td>exalar cheiro; cheirar; feder</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0250-11\" data-source=\"BDAG\" data-search=\"ὅθεν advérbio de onde; donde; por isso; portanto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅθεν</td><td>advérbio</td><td>de onde; donde; por isso; portanto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0250-12\" data-source=\"BDAG\" data-search=\"ὀθόνη, ης, ἡ substantivo feminino pano de linho; lençol; vela de embarcação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀθόνη, ης, ἡ</td><td>substantivo feminino</td><td>pano de linho; lençol; vela de embarcação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0250-13\" data-source=\"BDAG\" data-search=\"ὀθόνιον, ου, τό substantivo neutro tecido de linho; pano; faixas de tecido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀθόνιον, ου, τό</td><td>substantivo neutro</td><td>tecido de linho; pano; faixas de tecido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0250-14\" data-source=\"BDAG\" data-search=\"οἶδα verbo: perfeito com sentido de presente saber; conhecer; compreender; lembrar-se; honrar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἶδα</td><td>verbo: perfeito com sentido de presente</td><td>saber; conhecer; compreender; lembrar-se; honrar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0250-15\" data-source=\"BDAG\" data-search=\"οἰκεῖος, (α,) ον adjetivo substantivado membro da família; integrante da casa; familiar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκεῖος, (α,) ον</td><td>adjetivo substantivado</td><td>membro da família; integrante da casa; familiar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0250-16\" data-source=\"BDAG\" data-search=\"οἰκετεία, ας, ἡ substantivo feminino conjunto de escravos domésticos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκετεία, ας, ἡ</td><td>substantivo feminino</td><td>conjunto de escravos domésticos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0250-17\" data-source=\"BDAG\" data-search=\"οἰκέτης, ου, ὁ substantivo masculino escravo doméstico; servo da casa; escravo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκέτης, ου, ὁ</td><td>substantivo masculino</td><td>escravo doméstico; servo da casa; escravo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0250-18\" data-source=\"BDAG\" data-search=\"οἰκέω verbo residir; morar; habitar; ocupar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκέω</td><td>verbo</td><td>residir; morar; habitar; ocupar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0250-19\" data-source=\"BDAG\" data-search=\"οἴκημα, ατος, τό substantivo neutro quarto; aposento; cela BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἴκημα, ατος, τό</td><td>substantivo neutro</td><td>quarto; aposento; cela</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0250-20\" data-source=\"BDAG\" data-search=\"οἴκησις, εως, ἡ substantivo feminino casa; residência; habitação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἴκησις, εως, ἡ</td><td>substantivo feminino</td><td>casa; residência; habitação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0250-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁδός, οῦ, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁδός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ἡ</span> (Hom. e posteriores), geralmente um «caminho» ou «curso» estabelecido, como uma estrada ou o leito de um rio.</p><p class=\"entry-text\">① Via utilizada para viajar ou deslocar-se de um lugar a outro, caminho, estrada, via pública, empregada por pessoas ou entidades impessoais: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:12</a>; 21:8ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:5</a> (Is 40:4 v.l.); 19:36 e outros; <span class=\"greek\">ἑτέρα</span> <span class=\"greek\">ὁδ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:25</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">Καμπανή</span> = latim Via Campana, estrada da Campânia Hv 4, 1, 2 (ver MDibelius, Hdb. ad loc.; Hülsen, Pauly-W. III 1434); descrita como <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">δημοσία</span>, a via pública, ibidem (ver <span class=\"greek\">δημόσιος</span> 1). <span class=\"greek\">τὴν</span> <span class=\"greek\">βασιλικήν</span> AcPl Ant 13 (<span class=\"greek\">τὴν</span> <span class=\"greek\">β</span>. <span class=\"greek\">ὁδόν</span> Aa I 237, 4). <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">καταβαίνουσα</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Ἰερουσαλὴμ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Γάζαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:26</a>. <span class=\"greek\">παρέρχεσθαι</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδ</span>., passar (por determinado lugar) pela estrada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:28</a> (sobre <span class=\"greek\">διὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὁδ</span>., cf. Philo, Abr. 269; ParJer 3:21). <span class=\"greek\">πίπτειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδ</span>., cair na estrada Hv 3, 7, 1a. <span class=\"greek\">ἔρχεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδ</span>., <span class=\"greek\">μένειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁδ</span>. v 3, 2, 9a. <span class=\"greek\">κυλίεσθαι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδ</span>., rolar para fora da estrada 3, 2, 9b e 3, 7, 1b. Sobre uma figueira: <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδοῦ</span>, junto da estrada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:19</a>. Sobre mendigos: <span class=\"greek\">καθῆσθαι</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδ</span>., sentar-se à beira do caminho 20:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:35</a> (Stephan. Byz. s.v. <span class=\"greek\">Εὔτρησις</span>: <span class=\"greek\">κώμη</span> … <span class=\"greek\">κεῖται</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδόν</span>); entretanto, a ideia de «ao longo do caminho» também merece consideração (cf. <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ὁδούς</span> Antig. Car. 29). Sobre semente semeada: <span class=\"greek\">πίπτειν</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδ</span>., cair ao longo do caminho (Dalman, PJ 22, 1926, 121ff) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:5</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:12</a>. <span class=\"greek\">ἐξέρχεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ὁδ</span>., sair para as ruas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:23</a>; sobre <span class=\"greek\">διεξόδους</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὁδ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:9</a>, ver <span class=\"greek\">διέξοδος</span>; <span class=\"greek\">καταβαίνειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁδ</span>., descer pela estrada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:31</a>. <span class=\"greek\">πορεύεσθαι</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδ</span>., prosseguir pela estrada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:36</a>. AcPl Ant 13, 20 (subentende-se <span class=\"greek\">ὁδόν</span>, depois de AcPlTh 3=Aa I 237, 4). <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁδῷ</span> <span class=\"greek\">ᾗ</span> <span class=\"greek\">ἤρχου</span> (por atração, em vez de <span class=\"greek\">ἣν</span> <span class=\"greek\">ἤρ</span>.; X., An. 2, 2, 10) 9:17. <span class=\"greek\">ἑτοιμάζειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">τινος</span>, preparar o caminho de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:4</a> (todos segundo Is 40:3); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.76\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:76</a> e, para o passivo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:12</a>. Também <span class=\"greek\">κατασκευάζειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:27</a>. <span class=\"greek\">εὐθύνειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:23</a>. <span class=\"greek\">κατευθύνειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:11</a> (PsSol 8:6).—Com genitivo objetivo para indicar direção (Gen 3:24) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:5</a> (ver 3a abaixo); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:8</a>.—O acusativo <span class=\"greek\">ὁδόν</span>, segundo o hebraico <span class=\"hebrew\" lang=\"he\" dir=\"rtl\">דֶּרֶךְ</span> e contrariamente ao emprego grego costumeiro (embora casos isolados de <span class=\"greek\">ὁδός</span> também assumam funções de advérbios ou preposições no grego: cf. Diog. L. 7, 156; Synes., Providence 1, 8 <span class=\"greek\">ὁδῷ</span> <span class=\"greek\">βαδίζειν</span> = «ir diretamente em frente»; Appian, Hann. 47 §201 <span class=\"greek\">ὁδὸν</span> <span class=\"greek\">ἐλάσσονα</span>, por caminho mais curto [ou o mais curto]; Plut., Mor. 371c.—O paralelo mais próximo do uso neotestamentário citado abaixo seria o relato de Diog. L. 9, 8 sobre Heráclito: <span class=\"greek\">τὴν</span> <span class=\"greek\">μεταβολὴν</span> <span class=\"greek\">ὁδὸν</span> <span class=\"greek\">ἄνω</span> <span class=\"greek\">κάτω</span> <span class=\"greek\">γίνεσθαι</span>, caso se possa traduzir «A mudança [no universo] acontece numa direção ascendente e descendente»), é empregado como preposição com sentido de em direção a (Dt 11:30; 3 Km 8:48; 18:43 <span class=\"greek\">ὁδὸν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θαλάσσης</span>. Cf. B-D-F §161, 1): <span class=\"greek\">ὁδ</span>. <span class=\"greek\">θαλάσσης</span>, em direção ao mar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:15</a> (Is 8:23 LXX, Aq., Sym.).—LCasson, Travel in the Ancient World ’74; OEANE IV 431–34.</p><p class=\"entry-text\">② Ação de viajar, caminho, percurso, viagem, sentido transferido de 1 (Hes., Theogon. 754; X., Mem. 3, 13, 5; Herodian 2, 11, 1; JosAs 9:4 e outros; Just., D. 85, 5): <span class=\"greek\">εἰς</span> (<span class=\"greek\">τὴν</span>) <span class=\"greek\">ὁδ</span>., para a viagem (Jos., Ant. 12, 198) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:3</a>; a caminho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:17</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁδῷ</span>, no caminho (Gen 45:24; Jos., Ant. 6, 55; Ps.-Clem., Hom. 10, 2, final) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:32</a>; 20:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:3</a>, 27; 9:33f; 10:52; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.57\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:57</a>; 12:58; 24:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:27</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁδῷ</span>, o que lhes acontecera no caminho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:35</a>. <span class=\"greek\">εἶναι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁδῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:32</a>. <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὁδοῦ</span>, proveniente de viagem (Appian, Bell. Civ. 1, 91 §418; Damasc., Vi. Isid. 203 p. 138, 8 W.; Jos., Vi. 246; 248 <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὁδοῦ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:6</a>. <span class=\"greek\">ἔκαμνον</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδοῦ</span> GJs 15:1. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδ</span>., ao longo do caminho (Arrian, Anab. 1, 26, 5; 3, 19, 3; PKöln VI, 245, 20 <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὁδόν</span>, «em meu caminho»; Jos., Ant. 8, 404; Ps.-Clem., Hom. 10, 2) 10:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:3</a>; 26:13. <span class=\"greek\">ἀνὰ</span> <span class=\"greek\">μέσον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδοῦ</span>, no meio do caminho GJs 17:3. <span class=\"greek\">τ</span>. <span class=\"greek\">ὁδὸν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">πορεύεσθαι</span>, seguir seu caminho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:39</a> (cf. X., Cyr. 5, 2, 22; TestAbr B 2 p. 106, 2 [Stone p. 60]). <span class=\"greek\">πορεύεσθαι</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁδῷ</span> 1 Cl 12:4. <span class=\"greek\">ὁδὸν</span> <span class=\"greek\">ποιεῖν</span>, abrir caminho (Judg 17:8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:23</a>; ver <span class=\"greek\">ὁδοποιέω</span>.—<span class=\"greek\">σαββάτου</span> <span class=\"greek\">ὁδός</span>, jornada de um dia de sábado, também pode pertencer à acepção 1; designava a distância que um israelita podia percorrer no sábado, dois mil passos ou côvados (= cerca de 800 metros.—Mishná: ˓Erubin 4, 3; 7; 5, 7; Origen, Princ. 4, 17; Schürer II 472f; 484f; Billerb. II 590–94; Moore, Judaism II 32) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:12</a>. <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">ὁδός</span>, jornada de um dia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:44</a> (Diod S 19, 17, 3; Appian, Samn. 1 §5; Polyaenus 7, 21, 1; Lucian, Syr. Dea 9; Procop., Aed. 6, 1, 12; cf. Hdt. 4, 101; X., Cyr. 1, 1, 3 <span class=\"greek\">παμπόλλων</span> <span class=\"greek\">ἡμερῶν</span> <span class=\"greek\">ὁδός</span>; Ael. Aristid. 36, 87 K.=48 p. 473 D.: <span class=\"greek\">τριῶν</span> <span class=\"greek\">ἡμ</span>. <span class=\"greek\">ὁδ</span>.; Gen 30:36; 31:23; Ex 3:18; Jdth 2:21; 1 Macc 5:24; 7:45; Demetr.: 722 Fgm. 5 Jac.; Jos., Ant. 15, 293).</p><p class=\"entry-text\">③ Modo de comportar-se, caminho, modo de vida, extensão figurada de 1 e 2, embora frequentemente permaneça viva a imagem do caminho (SibOr 3, 233; <span class=\"greek\">ὁδὸς</span> <span class=\"greek\">τις</span> <span class=\"greek\">γίνεται</span>, encontra-se uma saída, Did., Gen. 228, 7).</p><p class=\"entry-text\">ⓐ Caminho: <span class=\"greek\">εἰς</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">ἐθνῶν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀπέλθητε</span>, não sigais pelo caminho dos gentios, isto é, não vos dirijais aos gentios <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:5</a> (mas ver acepção 1.—JJeremias, Jesu Verheissung für d. Völker, ’56). <span class=\"greek\">εὐρύχωρος</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀπάγουσα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀπώλειαν</span> 7:13 (Pla., Gorg. 524a <span class=\"greek\">τὼ</span> <span class=\"greek\">ὁδώ</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μακάρων</span> <span class=\"greek\">νήσους</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">εἰς</span> <span class=\"greek\">Τάρταρον</span>). Também <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀπωλείας</span> ApcPt 1:1; <span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μέλανος</span> <span class=\"greek\">ὁδ</span>. 20:1. <span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θανάτου</span> <span class=\"greek\">ὁδ</span>. (Herm. Wr. 1, 29) D 5:1. Cf. 1:1 (a respeito, Jer 21:8; TestAsh 1:3, 5 <span class=\"greek\">ὁδοὶ</span> <span class=\"greek\">δύο</span>, <span class=\"greek\">καλοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">κακοῦ</span>; SibOr 8, 399 <span class=\"greek\">ὁδοὶ</span> <span class=\"greek\">δύο</span>, <span class=\"greek\">ζωῆς</span> <span class=\"greek\">θανάτου</span> <span class=\"greek\">τε</span>; Ael. Aristid. 30 p. 577 D.: <span class=\"greek\">δυοῖν</span> <span class=\"greek\">ὁδοῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">τὴν</span> <span class=\"greek\">δέ</span>.—Os dois <span class=\"greek\">ὁδοί</span> de Héracles: X., Mem. 2, 1, 21ff; Maximus Tyr. 14, 1a; e; k). <span class=\"greek\">ὁδ</span>. <span class=\"greek\">σκότους</span> 5:4b. Descrição do caminho B 20; D 5:1ff. <span class=\"greek\">τεθλιμμένη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀπάγουσα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ζωήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:14</a> (TestAbr A 2 p. 88, 28 [Stone p. 4]). Também <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> D 1:2. <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">φωτός</span> 19:1. Descrição do caminho B 19; D 1–4. <span class=\"greek\">ὁδ</span>. <span class=\"greek\">εἰρήνης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.79\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:79</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:17</a> (Is 59:8; Ps 13:3). <span class=\"greek\">ὁδ</span>. <span class=\"greek\">ζωῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:28</a> (Ps 15:11); cf. D 1:2 acima. <span class=\"greek\">ὁδ</span>. <span class=\"greek\">σωτηρίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:17</a>. <span class=\"greek\">ὁδ</span>. <span class=\"greek\">πρόσφατος</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ζῶσα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.20\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:20</a>. <span class=\"greek\">ὁδ</span>. <span class=\"greek\">δικαιοσύνης</span> B 1:4; 5:4a (nessas duas passagens a imagem de «caminho» é mais forte que em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:32</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:21</a>; para essas duas passagens, ver abaixo b). Sobre o amor: <span class=\"greek\">ὁδ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀναφέρουσα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">θεόν</span> IEph 9:1 (cf. Orig., C. Cels. 1, 56, 6 [Cristo como mestre do «caminho»]). <span class=\"greek\">αὕτη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾗ</span> <span class=\"greek\">εὕρομεν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σωτήριον</span> <span class=\"greek\">ἡμῶν</span> 1 Cl 36:1.—Cristo designa a si próprio <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁδ</span>. (isto é, para Deus) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:6</a>, cf. 4f (ver Orig., C. Cels. 6, 66, 28; cf. Iren. 1, 15, 2 [Harv. I 149, 6].—Hdb. e Bultmann [p. 466ff—inglês 603ff, com outra bibliografia]; JPascher, <span class=\"greek\">Η</span> <span class=\"greek\">ΒΑΣΙΛΙΚΗ</span> <span class=\"greek\">ΟΔΟΣ</span>; D. Königsweg. z. Wiedergeb. u. Vergottung b. Philon v. Alex. ’31).</p><p class=\"entry-text\">ⓑ Modo de vida, maneira de agir, conduta (Did., Gen. 168, 8): (<span class=\"greek\">ἡ</span>) <span class=\"greek\">ὁδ</span>. (<span class=\"greek\">τῆς</span>) <span class=\"greek\">δικαιοσύνης</span> (Pr 21:16, 21; Job 24:13); En 99:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:32</a> (<span class=\"greek\">ἐν</span> <span class=\"greek\">ὁδῷ</span> <span class=\"greek\">δικ</span>. [cf. Pr 8:20] designa seja o modo de vida praticado pelo Batista [Zahn; OHoltzmann], seja o tipo de conduta que exigia [descrito em Just., D. 38, 2 como <span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βαπτίσματο</span> <span class=\"greek\">ὁδ</span>.; cf. HHoltzmann; BWeiss; JWeiss; EKlostermann; Schniewind]. Ver JKleist, CBQ 8, ’46, 192–96); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:21</a>. <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἐπλανήθη</span>, desviou-se do caminho (= «de sua conduta») 1 Cl 16:6 (Is 53:6). <span class=\"greek\">ἐκ</span> <span class=\"greek\">πλάνης</span> <span class=\"greek\">ὁδοῦ</span> <span class=\"greek\">αὐτοῦ</span>, de seu modo de vida errôneo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:20</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span> (Ps 118:30), versículo 19 v.l. (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:2</a> em c abaixo); 1 Cl 35:5. <span class=\"greek\">ἀφιέναι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀληθινήν</span> Hv 3, 7, 1. <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Κάϊν</span> <span class=\"greek\">πορεύεσθαι</span>, seguir o caminho de Caim Jd 11. <span class=\"greek\">ὁδ</span>. <span class=\"greek\">δικαίων</span>, <span class=\"greek\">ἀσεβῶν</span> 11:7 (Ps 1:6). (<span class=\"greek\">ἡ</span>) <span class=\"greek\">ὁδ</span>. (<span class=\"greek\">ἡ</span>) <span class=\"greek\">δικαία</span> (Jos., Ant. 13, 290) 12:4; 2 Cl 5:7. <span class=\"greek\">τὸ</span> <span class=\"greek\">δίκαιον</span> <span class=\"greek\">ὀρθὴν</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">ἔχει</span>, o caminho da justiça é reto Hm 6, 1, 2. <span class=\"greek\">τῇ</span> <span class=\"greek\">ὀρθῇ</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">πορεύεσθαι</span>, percorrer o caminho reto, ibidem; cf. 6, 1, 4 (Just., D. 8, 2). Em oposição, <span class=\"greek\">ἡ</span> <span class=\"greek\">στρεβλὴ</span> <span class=\"greek\">ὁδ</span>., o caminho tortuoso 6, 1, 3. <span class=\"greek\">θέωμεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">εὐθεῖαν</span>, corramos pelo caminho reto 2 Cl 7:3; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:15</a>. Sobre a vida em associação com politeístas: <span class=\"greek\">αὕτη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">ἡδυτέρα</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ἐφαίνετο</span> Hs 8, 9, 1. O significado básico desapareceu a tal ponto que se pode falar de <span class=\"greek\">καρποὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδ</span>. 1 Cl 57:6 (Pr 1:31) e <span class=\"greek\">ἔργα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πονηρᾶς</span> <span class=\"greek\">ὁδ</span>. 4:10.—Plural, caminhos, a respeito da totalidade da conduta de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:16</a> (Is 59:7; Ps 13:3a; PsSol 6:2; 10:4 e outros; ApcSed 15:5); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:8</a>; Hv 2, 2, 6. Especialmente sobre os caminhos de Deus, quer as ações que ele inicia: <span class=\"greek\">ὡς</span> … <span class=\"greek\">ἀνεξιχνίαστοι</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">αὐτοῦ</span>, quão inescrutáveis são seus caminhos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:33</a>; <span class=\"greek\">δίκαιαι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀληθιναὶ</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">σου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 15:3</a>; <span class=\"greek\">αἱ</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">εὐλογίας</span>, os caminhos da bênção 1 Cl 31:1; quer os caminhos que as pessoas devem seguir: <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔγνωσαν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:10</a> (Ps 94:10). <span class=\"greek\">διαστρέφειν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ὁδοὺς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:10</a>. <span class=\"greek\">διδάσκειν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">σου</span> 1 Cl 18:13 (Ps 50:15). Igualmente o singular: <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀληθείᾳ</span> <span class=\"greek\">διδάσκειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:16</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:21</a>. <span class=\"greek\">ἀφιέναι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> ApcPt 20:34. <span class=\"greek\">παρέβησαν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδ</span>. 1 Cl 53:2 (Ex 32:8).</p><p class=\"entry-text\">ⓒ Sobre o modo de vida inteiro, do ponto de vista moral e espiritual, o Caminho, ensinamento em sentido abrangente (Lucian, Hermot. 46, <span class=\"greek\">ὁδ</span>. da doutrina de escola filosófica; Just., D. 39, 2 <span class=\"greek\">ἀπολείποντας</span> <span class=\"greek\">τήν</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πλάνης</span>; 142, 3 <span class=\"greek\">διὰ</span> <span class=\"greek\">ταύτης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδοῦ</span>), particularmente sobre o ensinamento e modo de vida relacionados a Jesus Cristo (SMcCasland, JBL 77, ’58, 222–30: paralelos de Qumran): <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">ἣν</span> <span class=\"greek\">λέγουσιν</span> <span class=\"greek\">αἵρεσιν</span>, segundo o Caminho que chamam seita (heterodoxa) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:14</a>. <span class=\"greek\">ἐάν</span> <span class=\"greek\">τινας</span> <span class=\"greek\">εὕρῃ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">ὄντας</span>, caso encontrasse pessoas pertencentes ao Caminho 9:2. <span class=\"greek\">ὁδ</span>. <span class=\"greek\">κυρίου</span>, <span class=\"greek\">θεοῦ</span>, referente ao ensinamento sobre Jesus e o propósito de Deus 18:25f. <span class=\"greek\">κακολογεῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πλήθους</span> 19:9. <span class=\"greek\">ταύτην</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">διώκειν</span>, perseguir esta religião 22:4. <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">τάραχος</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδ</span>., surgiu perturbação a respeito do Caminho 19:23. <span class=\"greek\">τὰ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδ</span>., as coisas referentes ao ensinamento 24:22. <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁδὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀληθείας</span>, acerca do verdadeiro ensinamento cristão (em oposição ao dos dissidentes no versículo 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:2</a> (OdeSol 11:3). Acerca do caminho do amor: <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὑπερβολὴν</span> <span class=\"greek\">ὁδ</span>., caminho muito superior <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:31</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁδ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">δικαιοσύνης</span> ApcPt 7:22; 13:28. Igualmente o plural (En 104:13 <span class=\"greek\">μαθεῖν</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">αὐτῶν</span> [<span class=\"greek\">τ</span>. <span class=\"greek\">βίβλων</span>] <span class=\"greek\">πάσας</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὁδοὺς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span>): <span class=\"greek\">τὰς</span> <span class=\"greek\">ὁδούς</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span> <span class=\"greek\">Ἰησου</span>, minhas orientações cristãs (isto é, instruções, ensinamentos) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:17</a>.—OBecker, D. Bild des Weges u. verwandte Vorstellungen im frühgriech. Denken ’37; FNötscher, Gotteswege u. Menschenwege in d. Bibel u. in Qumran, ’58; ERepo, D. Weg als Selbstbezeichnung des Urchr., ’64 (mas ver CBurchard, Der 13te Zeuge, ’70, 43, nota 10; JPathrapankal, Christianity as a ‘Way’ according to the Acts of the Apostles: Les Actes des Apôtres, Traditions, redaction, théologie, ed. JKremer ’79, 533–39 [reflete Is 40:3 e a ênfase em <span class=\"hebrew\" lang=\"he\" dir=\"rtl\">דרך</span> em CD e 1QS: o «dinamismo do cristianismo» é «Caminho de Vida»]).—B. 717; 720. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0250-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀδούς, ὀδόντος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀδούς</span>, <span class=\"greek\">ὀδόντος</span>, <span class=\"greek\">ὁ</span> (Hom. e posteriores; papiros, LXX; PsSol 13:3; TestSol; ApcEsdr 4:30 p. 29, 6 Tdf.; ApcMos; Philo; Jos., Bell. 6, 197; Just., D. 57, 2), dente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:8</a> (cf. Jo 1:6). <span class=\"greek\">δι</span>’ <span class=\"greek\">ὀδόντων</span> <span class=\"greek\">θηρίων</span> <span class=\"greek\">ἀλήθεσθαι</span>, ser triturado pelos dentes de feras IRo 4:1. Com <span class=\"greek\">ὀφθαλμός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:38</a> (Ex 21:24). <span class=\"greek\">τρίζειν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὀδ</span>., ranger os dentes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:18</a>. Também <span class=\"greek\">βρύχειν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὀδ</span>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> (ver <span class=\"greek\">βρύχω</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.54\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:54</a>. Daí <span class=\"greek\">βρυγμὸς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὀδ</span>., ranger ou atritar de dentes (com <span class=\"greek\">κλαυθμός</span>), somente em conexão com tormentos do inferno <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:12</a>; 13:42, 50; 22:13; 24:51; 25:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:28</a> (ver <span class=\"greek\">βρυγμός</span>).—B. 231. DELG s.v. <span class=\"greek\">ὀδών</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0250-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀδυνάω</h1><div class=\"entry-meta\"><span>verbo; na literatura, médio-passivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀδυνάω</span> (<span class=\"greek\">ὀδύνη</span>), passivo, futuro, 3ª pessoa do singular <span class=\"greek\">ὀδυνηθήσεται</span> LXX; aoristo, 3ª pessoa do singular <span class=\"greek\">ὠδυνήθη</span> 4 Macc 18:9, «causar dor»; em nossa literatura somente no passivo <span class=\"greek\">ὀδυνάομαι</span>, 2ª pessoa <span class=\"greek\">ὀδυνᾶσαι</span> (B-D-F §87; W-S. §13, 17; Mlt-H. 198; Helbing p. 61), «sentir dor» (autores trágicos e outros; Democr. 159; Pla.; Vett. Val. índice; LXX; TestJob 24:4; TestIss 7:5; ParJer 7:31).</p><p class=\"entry-text\">① Experimentar tormento físico, sofrer dor (Aelian, NA 11, 32 p. 286, 28); <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, sofrer dor por alguém 1 Cl 16:4 (Is 53:4). Especialmente os tormentos no Hades: <span class=\"greek\">ὀδ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">φλογί</span>, sofrer tormentos nas chamas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:24</a>; cf. versículo 25.</p><p class=\"entry-text\">② Experimentar dor mental e espiritual, afligir-se, angustiar-se (Dio Chrys. 66 [16], 1; Alciphron 3, 14, 2; Philo, De Jos. 94 <span class=\"greek\">ὀδυνώμενος</span>; Jos., Bell. 6, 183 <span class=\"greek\">ὀδυνώμενον</span>): <span class=\"greek\">ὀδυνώμενοι</span> <span class=\"greek\">ζητοῦμέν</span> <span class=\"greek\">σε</span>, procurávamos-te angustiados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:48</a> (duas pessoas de sexos diferentes referidas com modificador masculino, como em Epici p. 20, 3 K. [p. 42, 60 B.], Aquiles e Helena com <span class=\"greek\">αὐτούς</span>). <span class=\"greek\">ὀδυνώμενοι</span> <span class=\"greek\">μάλιστα</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span>, ficaram especialmente aflitos com o que ele dissera <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:38</a> (<span class=\"greek\">ὀδυνᾶσθαι</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span>, como Philo, Conf. Lingu. 92).—DELG s.v. <span class=\"greek\">ὀδύνη</span>. M-M s.v. <span class=\"greek\">ὀδυνάομαι</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0250-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀδύνη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀδύνη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (ver o verbete precedente; Hom. e outros; PGrenf I, 1, 2 [II b.c.]; Sb 4949, 12; 5716, 12; LXX; En 102:11; PsSol 4:15; TestSol 4:9 D; TestJob; Test12Patr; ApcMos 25; EpArist 208; Philo; Jos., Ant. 15, 62, C. Ap. 2, 143).</p><p class=\"entry-text\">① Sofrimento ou miséria física, dor, aflição: <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀδ</span>. AcPl Ha 5, 30 (por ferimento); sobre as tribulações dos últimos dias <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:8</a> v.l. (sobre o itacismo, ver <span class=\"greek\">ὠδίν</span>).</p><p class=\"entry-text\">② Dor mental, aflição: <span class=\"greek\">ἀδιάλειπτος</span> <span class=\"greek\">ὀδ</span>. <span class=\"greek\">τῇ</span> <span class=\"greek\">καρδίᾳ</span> <span class=\"greek\">μου</span> (subentende-se <span class=\"greek\">ἐστί</span>), meu coração está continuamente entristecido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:2</a> (Philo, Aet. M. 63 <span class=\"greek\">ὀδ</span>. <span class=\"greek\">ψυχῆς</span>). Acerca do remorso da consciência: <span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">περιέπειραν</span> <span class=\"greek\">ὀδύναις</span> <span class=\"greek\">πολλαῖς</span>, traspassaram-se com muitas dores <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:10</a>.—Schmidt, Syn. II 596–610. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0250-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀδύνω, οῦ, ὁ</h1><div class=\"entry-meta\"><span>forma verbal de leitura variante</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀδύνω</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">ὀδύνη</span>) (<span class=\"greek\">ὀδύνομαι</span> TestIss 7:5), sentir dor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:22</a> v.l. (em lugar de <span class=\"greek\">συνωδίνω</span>), talvez por influência de <span class=\"greek\">ὀδυνάω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0250-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀδυρμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀδυρμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">ὀδύρομαι</span>; Aeschyl., Pla. e outros; Aelian, VH 14, 22; TestSol 4:2 D; Jos., Bell. 5, 31, Ant. 2, 328; 2 Macc 11:6), lamentação, pranto, luto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:7</a>. Com <span class=\"greek\">κλαυθμός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:18</a> (Jer 38:15).—DELG s.v. <span class=\"greek\">ὀδύρομαι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0250-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀδύρομαι</h1><div class=\"entry-meta\"><span>verbo médio depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀδύρομαι</span>, médio depoente (ver verbete anterior; Hom. e outros; inscrição de Gaza: SEG VIII, 269, 8 [III/II b.c.]; PThéad. 21, 15; Ramsay, Studies in the History and Art of the Eastern Provinces 1906, 144, 5; Jer 38:18; TestAbr A; TestZeb 2:4; 4:6, ambos v.l.; GrBar 13:1; ApcSed 11:1 p. 134, 9 Ja.; ApcMos 27; Philo, Migr. Abr. 156; Jos., Ant. 11, 222, C. Ap. 2, 243; Just., D. 83, 3; Ath. 21, 2), lamentar, prantear, com <span class=\"greek\">ἐλεεῖν</span> MPol 2:2.—DELG. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0250-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ὀζίας, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ὀζίας</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (-<span class=\"greek\">είας</span>.—<span class=\"hebrew\" lang=\"he\" dir=\"rtl\">עֻזִּיָּהוּ</span> <span class=\"hebrew\" lang=\"he\" dir=\"rtl\">עֻזִּיָּה</span>; <span class=\"greek\">Ὀζίας</span> na LXX e em Joseph.; ver EKautzsch, Mitteilungen u. Nachrichten des Deutschen Palästina-Vereins 1904, 6f; BHHW III 2068f), Uzias, rei hebreu, na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:8</a>f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:23</a>ff D (aqui, como em Jos., Ant. 9, 236, o genitivo é <span class=\"greek\">Ὀζία</span>).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0250-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄζος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄζος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom. e outros, «ramo»), nó em galho de árvore (assim em Theophr. e outros; Wsd 13:13): <span class=\"greek\">ῥάβδος</span> <span class=\"greek\">σκληρὰ</span> <span class=\"greek\">λίαν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὄζους</span> <span class=\"greek\">ἔχουσα</span>, um bastão muito duro e nodoso Hs 6, 2, 5 (cf. Alciphron 3, 19, 5).—B. 523. DELG 1 <span class=\"greek\">ὄζος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0250-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄζω</span>, 1º aoristo, 3ª pessoa do singular <span class=\"greek\">ὤζεσεν</span> Ex 8:10; ParJer 6:8 (Hom. e outros; Antig. Car. 117; Plut., Phoc. 751 [22] [odor emanado de cadáver]; cf. PSI IV, 297, 3 [V a.d.?]; Epict. 4, 11, 15; 18 [sobre homem descuidado]), emitir odor, agradável ou desagradável, cheirar; <span class=\"greek\">ἤδη</span> <span class=\"greek\">ὄζει</span>, a esta altura já cheira (mal), já fede <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:39</a>.—B. 551. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0250-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅθεν</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅθεν</span>, advérbio (Hom. e posteriores).</p><p class=\"entry-text\">① Extensão a partir de uma origem indicada pelo elemento inicial, de onde, donde, do qual.</p><p class=\"entry-text\">ⓐ Em referência a lugar (TestAbr A; JosAs; Jos., Ant. 1, 168; 19, 291; Tat. 5:2) GPt 13:56; Hs 9, 4, 7. <span class=\"greek\">ὅθ</span>. <span class=\"greek\">ἐξῆλθον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:24</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἀντιόχειαν</span> <span class=\"greek\">ὅθ</span>. <span class=\"greek\">ἦσαν</span> <span class=\"greek\">παραδεδομένοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:26</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">Συρακούσας</span> … <span class=\"greek\">ὅθ</span>. <span class=\"greek\">περιελθόντες</span> <span class=\"greek\">κατηντήσαμεν</span> 28:13. Com atração (Thu. 1, 89, 3.—B-D-F §437; Rob. 548): <span class=\"greek\">συνάγων</span> <span class=\"greek\">ὅθ</span>. (<span class=\"greek\">ἐκεῖθεν</span> <span class=\"greek\">ὅπου</span>) <span class=\"greek\">οὐ</span> <span class=\"greek\">διεσκόρπισας</span>, recolhendo onde não espalhaste <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:24</a>, 26.</p><p class=\"entry-text\">ⓑ Em referência a dedução feita de uma circunstância, a partir desse fato (Jos., Ant. 2, 36; Ar 4:2 e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:18</a>.</p><p class=\"entry-text\">② Marcador de fundamento para ação ou procedimento, razão pela qual, por isso (Pla., Aristot.; inscrições [Meisterhans3-Schw. p. 253]; UPZ 162 II, 4 [117 b.c.]; BGU 731 II, 12; LXX; Demetr.: 722 Fgm. 1, 7 Jac.; Ath. 22, 6); no início de oração, portanto, daí (Diod S 14, 51, 5; Appian, Liby. 47 §202; Ps.-Callisth. 2, 1, 4; Wsd 12:23; Jdth 8:20; TestNapht 1:8; EpArist 110; Jos., Ant. 19, 203, Vi. 338; Ar. 8, 4; Just., A I, 12, 10 e outros.—B-D-F §451, 6; Rob. 962) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:17</a>; 3:1; 7:25; 8:3; 9:18; 11:19 (ou «dentre os quais», ver Goodsp.); 2 Cl 5:1; IEph 4:1.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0250-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀθόνη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀθόνη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (ver o verbete seguinte; Hom. e outros; papiros; JosAs 2:7; Jos., Ant. 5, 290; 12, 117), pano de linho, lençol (Appian, Bell. Civ. 4, 47 §200) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:11</a>; 11:5. Especialmente, vela de embarcação (IAndrosIsis [I b.c.] 153; Lucian, Jupp. Tr. 46, Ver. Hist. 2, 38; TestZeb 6:2): <span class=\"greek\">ὀθ</span>. <span class=\"greek\">πλοίου</span>, vela de navio MPol 15:2.—DELG. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0250-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀθόνιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀθόνιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Aristoph., Hippocr. e outros; inscrições [por exemplo, a Pedra de Roseta: OGI 90, 18 (196 b.c.)]; papiros [por exemplo, UPZ 85, 8; 42–163/160 b.c.]; Judg 14:13 B; Hos 2:7, 11; EpArist 320; JosAs 13:5 códice A [p. 57, 11 Bat.]. Cf. O. Wilck I p. 266ff. Sobre a origem da palavra, ver HLewy, Die semit. Fremdwörter im Griech. 1895, 124f; Thumb 111; sobre a planta do linho, ver Zohary, Plants 78, Geobot. II 628), diminutivo de <span class=\"greek\">ὀθόνη</span>, mas não necessariamente com valor diminutivo em nossa literatura; pano (de linho), tecido usado para envolver <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:40</a>; 20:5, 6, 7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:12</a>. É questionável a aplicação à nossa literatura do sentido atadura (UPZ 85, 8; PGiss 68, 11). Ver AVaccari, em Miscellanea biblica, BUbach ’53, 375–86, com referência a PRyl 627, 9 (IV a.d.]. Ver também JBlinzler, <span class=\"greek\">ΟΘΟΝΙΑ</span> etc.: Philol 99, ’55, 158–66; RBrown, AB: John 942 e JFitzmyer, AB: Luke 1548.—DELG s.v. <span class=\"greek\">ὀθόνη</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0250-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἶδα</h1><div class=\"entry-meta\"><span>verbo: perfeito com sentido de presente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἶδα</span> (Hom. e posteriores), na verdade perfeito do radical <span class=\"greek\">εἰδ</span>- (latim video), mas usado como presente; 2ª pessoa singular <span class=\"greek\">οἶδας</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:15</a>f), <span class=\"greek\">οἶσθα</span> (Dt 9:2; 4 Macc 6:27); 1ª pessoa plural <span class=\"greek\">οἴδαμεν</span> LXX; 2ª pessoa plural <span class=\"greek\">οἴδατε</span>; 3ª pessoa plural <span class=\"greek\">οἴδασιν</span> (<span class=\"greek\">ἴσασιν</span> somente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:4</a>. A forma <span class=\"greek\">οἴδασιν</span> já aparece em Hdt. 2, 43, 1; X., Oec. 20, 14; SIG 182, 8 [362/361 b.c.]; PCairGoodsp 3, 7 [III b.c.]; <span class=\"greek\">οἶδαν</span> GJs 17:1). <span class=\"greek\">ἴστε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:19</a> pode ser indicativo (assim 3 Macc 3:14) ou imperativo; subjuntivo <span class=\"greek\">εἰδῶ</span>; infinitivo <span class=\"greek\">εἰδέναι</span>; <span class=\"greek\">εἰδῆσαι</span> Dt 4:35; Jdth 9:14; particípio <span class=\"greek\">εἰδώς</span>, <span class=\"greek\">εἰδυῖα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:7</a>. Mais-que-perfeito <span class=\"greek\">ᾔδειν</span>, 2ª pessoa singular <span class=\"greek\">ᾔδεις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:22</a>, 3ª pessoa plural <span class=\"greek\">ᾔδεισαν</span> (W-S. §13, 20). Futuro <span class=\"greek\">εἰδήσω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:11</a> (Jer 38:34) e <span class=\"greek\">εἴσομαι</span> (Dg 12:1). B-D-F §99, 2; 101 p. 45 (<span class=\"greek\">εἰδέναι</span>); W-S. §14, 7; Mlt-H. 220–22; Helbing p. 108; Mayser 321, 2; 327, 17; 372f; sobre a relação com <span class=\"greek\">γινώσκω</span>, ver SPorter, Verbal Aspect in the Greek of the NT ’89, 282–87.</p><p class=\"entry-text\">① Possuir informação acerca de algo, saber, conhecer.</p><p class=\"entry-text\">ⓐ Com acusativo de pessoa: conhecer alguém, saber a respeito de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:26</a>, 31, 33; 6:42; 7:28a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:16</a>; 7:18 (Ex 1:8); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:30</a>; 10:11. (<span class=\"greek\">τὸν</span>) <span class=\"greek\">θεόν</span> (Herm. Wr. 14, 8; Ar. 3, 2; Just., D. 10, 4; Tat. 19, 2), acerca de politeístas, que nada sabem de Deus (o único Deus descrito nos versículos 6–7, em contraste com a pluralidade de deuses que anteriormente escravizavam os gálatas no versículo 8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:5</a> (cf. Jer 10:25).</p><p class=\"entry-text\">ⓑ Com acusativo de coisa: <span class=\"greek\">οὐ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὥραν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:13</a>; cf. 2 Cl 12:1. <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐντολάς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:20</a>. <span class=\"greek\">βρῶσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:32</a>. <span class=\"greek\">τ</span>. <span class=\"greek\">ἐνθυμήσεις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:4</a> v.l. (cf. Jos., Vi. 283). <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐπιθυμίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:7</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">μυστήρια</span> <span class=\"greek\">πάντα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:2</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐγκάρδια</span> 2 Cl 9:9. <span class=\"greek\">τὰ</span> <span class=\"greek\">κρύφια</span> IMg 3:2. <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span> Hs 1:1.</p><p class=\"entry-text\">ⓒ Com acusativo de pessoa e particípio em lugar do predicado (X., An. 1, 10, 16; TestJob 28:5; Just., A I, 12, 7.—B-D-F §416, 2; ver Rob. 1103): <span class=\"greek\">οἶδα</span> <span class=\"greek\">ἄνθρωπον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span> … <span class=\"greek\">ἁρπαγέντα</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τοιοῦτον</span> <span class=\"greek\">ἕως</span> <span class=\"greek\">τρίτου</span> <span class=\"greek\">οὐρανοῦ</span>, conheço uma pessoa em Cristo … que foi arrebatada até o terceiro céu <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:2</a>. Também sem particípio: <span class=\"greek\">εἰδὼς</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἄνδρα</span> <span class=\"greek\">δίκαιον</span> (subentende-se <span class=\"greek\">ὄντα</span>), por saber que ele era homem justo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:20</a> (Chion, Ep. 3, 5 <span class=\"greek\">ἴσθι</span> <span class=\"greek\">με</span> <span class=\"greek\">προθυμότερον</span> [<span class=\"greek\">ὄντα</span>]). O objeto pode ser mais precisamente definido por oração declarativa ou interrogativa: <span class=\"greek\">οἴδατε</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκίαν</span> <span class=\"greek\">Στεφανᾶ</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ἀπαρχὴ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἀχαί</span>̈<span class=\"greek\">ας</span> = <span class=\"greek\">οἴδατε</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">οἰκία</span> <span class=\"greek\">Στεφανᾶ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἀπαρχὴ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἀ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:15</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:3</a> v.l. Uma interrogativa indireta pode ocupar o lugar de <span class=\"greek\">ὅτι</span>: <span class=\"greek\">οἶδά</span> <span class=\"greek\">σε</span> <span class=\"greek\">τίς</span> <span class=\"greek\">εἶ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:34</a>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">οἶδα</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">πόθεν</span> <span class=\"greek\">ἐστέ</span>, não sei de onde sois 13:25; cf. versículo 27 (<span class=\"greek\">ὑμᾶς</span> não figura em todos os manuscritos aqui); 2 Cl 4:5. <span class=\"greek\">τοῦτον</span> <span class=\"greek\">οἴδαμεν</span> <span class=\"greek\">πόθεν</span> <span class=\"greek\">ἐστίν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:27</a>; 9:29b.</p><p class=\"entry-text\">ⓓ Seguido de acusativo e infinitivo (Just., A I, 26, 4; 59, 6, D. 75, 4.—B-D-F §397, 1; ver Rob. 1036ff) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:9</a>; 1 Cl 62:3.</p><p class=\"entry-text\">ⓔ Seguido de <span class=\"greek\">ὅτι</span> (Aeneas Tact. 579; Dio Chrys. 31 [48], 1; Maximus Tyr. 16, 2b; TestAbr A 6 p. 83, 14 [Stone p. 14]; JosAs 6:6 e outros; Just., A I, 12, 11; D. 4, 4 e outros.—B-D-F §397, 1; Rob. 1035) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:32</a>; 9:6; 15:12; 20:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:49</a>; 8:53; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:17</a> e muito frequentemente; GJs 4:4; 5:1; 17:1; 20:2 codd.; 23:2. <span class=\"greek\">εἰδὼς</span> (<span class=\"greek\">εἰδότες</span>) <span class=\"greek\">ὅτι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:30</a>; 1 Cl 45:7; 2 Cl 7:1; 10:5; B 10:11; 19:6; IMg 14; ISm 4:1; Hs 8, 6, 1; 10, 3, 4 [Ox 404 recto, 15]; Pol 1:3; 4:1; 5:1; 6:1; D 3:10; AcPl Ha 1, 25; AcPlCor 2:29.—<span class=\"greek\">τοῦτο</span>, <span class=\"greek\">ὅτι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:15</a>. <span class=\"greek\">ἓν</span> <span class=\"greek\">οἶδα</span>, <span class=\"greek\">ὅτι</span>, sei apenas uma coisa, que <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:25</a>b (Vi. Aesopi I c. 17 p. 269, 16f Eb. <span class=\"greek\">οὐκ</span> <span class=\"greek\">οἶδα</span>, <span class=\"greek\">τί</span> <span class=\"greek\">γέγονεν</span>. <span class=\"greek\">ἓν</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">οἶδα</span> <span class=\"greek\">μόνον</span>, <span class=\"greek\">ὅτι</span> … ).—A fórmula <span class=\"greek\">οἴδαμεν</span> <span class=\"greek\">ὅτι</span> é frequentemente utilizada para introduzir fato bem conhecido e geralmente aceito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:2</a>; 9:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:2</a>; 3:19; 7:14; 8:22, 28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:2</a>; 5:18ff. Paulo também emprega para esse fim a pergunta retórica (<span class=\"greek\">ἢ</span>) <span class=\"greek\">οὐκ</span> <span class=\"greek\">οἴδατε</span> <span class=\"greek\">ὅτι</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:16</a>; 5:6; 6:2f, 9, 15f, 19; 9:13, 24.</p><p class=\"entry-text\">ⓕ Com interrogativa indireta subsequente (TestAbr B 2 p. 106, 1 [Stone p. 60] <span class=\"greek\">μὴ</span> <span class=\"greek\">εἰδὼς</span> <span class=\"greek\">τίς</span> <span class=\"greek\">ἐστίν</span>; Just., D. 65, 1 <span class=\"greek\">οὐκ</span> <span class=\"greek\">οἶδα</span> <span class=\"greek\">τί</span> <span class=\"greek\">φῶ</span>): <span class=\"greek\">τίς</span>, <span class=\"greek\">τί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:6</a> (HBaltensweiler, D. Verklärung Jesu ’59, 114f; quanto à gramática e ao tema da inadequação diante da transcendência, cf. Eur., Bacch. 506; ver também 358); 10:38; 14:40; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:13</a>; 6:6; 9:21b; 13:18; 15:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:27</a>; 11:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:14</a>; IEph 12:1. <span class=\"greek\">ποῖος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:42</a>f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:39</a>. <span class=\"greek\">ἡλίκος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:1</a>. <span class=\"greek\">οἷος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:5</a>. <span class=\"greek\">ποῦ</span> (ParJer 5:13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:8</a>; 8:14; 12:35 14:5; 20:2, 13. <span class=\"greek\">πῶς</span> (BGU 37, 7; ApcMos 31) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:21</a>a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:15</a>; GJs 23:3. <span class=\"greek\">πότε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:33</a>, 35. <span class=\"greek\">πόθεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:9</a>a; 3:8; 7:28b; 8:14; 9:30. Seguido de <span class=\"greek\">εἰ</span>, se (Lucian, Tox. 22) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:16</a>ab (JJeremias, Bultmann Festschr. ’54, 255–66, entende <span class=\"greek\">τί</span> <span class=\"greek\">οἶδας</span> <span class=\"greek\">εἰ</span> como «talvez»; CBurchard, ZNW 61, ’70, 170f); Hm 12, 3, 4.—<span class=\"greek\">εἴτε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:2</a>f.</p><p class=\"entry-text\">ⓖ Seguido de relativo (PPetr II, 11 [1], 7 [III b.c.]): <span class=\"greek\">οἶδεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">χρείαν</span> <span class=\"greek\">ἔχετε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:8</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:12</a>.</p><p class=\"entry-text\">ⓗ Seguido de <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> (Just., D. 5, 1), saber acerca de algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:32</a> (RBrown, Jesus, God and Man ’67, 59–79).</p><p class=\"entry-text\">ⓘ Emprego absoluto (Just., A I, 21, 4 <span class=\"greek\">πρὸς</span> <span class=\"greek\">εἰδότας</span> <span class=\"greek\">λέγειν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀνάγκη</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:9</a>b; 1 Cl 43:6. <span class=\"greek\">καθὼς</span> (<span class=\"greek\">αὐτοὶ</span>) <span class=\"greek\">οἴδατε</span>, como (vós mesmos) sabeis <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:2</a>, 5; cf. 3:4. <span class=\"greek\">καίπερ</span> <span class=\"greek\">εἰδ</span>., embora saibais (essas coisas) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:12</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">οἶδεν</span>, Deus sabe (que o faço) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:11</a>; cf. 9:9. <span class=\"greek\">ἴστε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:19</a> (indicativo: HermvSoden; BWeiss; Weymouth; W-S. §14, 7; imperativo: Hollmann; MDibelius; Windisch; OHoltzmann; Hauck; Meinertz; NRSV «Deveis compreender isto»; B-D-F §99, 2; Mlt. 245).</p><p class=\"entry-text\">② Estar intimamente familiarizado com alguém ou manter relação estreita com alguém, conhecer: <span class=\"greek\">οὐκ</span> <span class=\"greek\">οἶδα</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄνθρωπον</span>, não conheço esse homem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.72\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:72</a>, 74; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.71\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:71</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.57\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:57</a>. <span class=\"greek\">ὥστε</span> <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">οὐδένα</span> <span class=\"greek\">οἴδαμεν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:16</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ᾔδει</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκί</span> AcPl Ant 13, 16 (em lugar disso <span class=\"greek\">εἶδεν</span> <span class=\"greek\">ἀυτὸν</span> <span class=\"greek\">σαρκί</span> Aa I 237, 2).—Conhecer a Deus, isto é, não apenas saber teoricamente que Deus existe, mas manter relação positiva com ele; ou não conhecer a Deus, isto é, não querer saber de Deus: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:16</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:28</a>b; 8:19 e outros.—<span class=\"greek\">οὐκ</span> <span class=\"greek\">οἶδα</span> <span class=\"greek\">ὑμᾶς</span>, nada tenho convosco <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:12</a>. Cf. fórmula de sentido semelhante pela qual mestre excluía discípulo por sete dias: Billerb. I 469; IV 293.</p><p class=\"entry-text\">③ Saber como fazer alguma coisa, poder, ser capaz, com infinitivo subsequente (X., Cyr. 1, 6, 46; Philosoph. Max. p. 497, 7 <span class=\"greek\">εἰδὼς</span> <span class=\"greek\">εὔχεσθαι</span>; Herodian 3, 4, 8; Jos., Bell. 2, 91; 5, 407): <span class=\"greek\">οἴδατε</span> <span class=\"greek\">δόματα</span> <span class=\"greek\">ἀγαθὰ</span> <span class=\"greek\">διδόναι</span>, sabeis dar boas dádivas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:13</a> (cf. TestJob 44:3 <span class=\"greek\">ᾔδεισαν</span> <span class=\"greek\">εὖ</span> <span class=\"greek\">ποιεῖν</span>). <span class=\"greek\">οἴδατε</span> <span class=\"greek\">δοκιμάζειν</span>, sabeis interpretar 12:56ab. <span class=\"greek\">οἶδα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ταπεινοῦσθαι</span>, <span class=\"greek\">οἶδα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">περισσεύειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:12</a>. <span class=\"greek\">εἰδέναι</span> <span class=\"greek\">ἕκαστον</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">σκεῦος</span> <span class=\"greek\">κτᾶσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἁγιασμῷ</span>, que cada um dentre vós saiba possuir o próprio vaso (ver <span class=\"greek\">σκεῦος</span> 3) em santificação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:4</a>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἰδίου</span> <span class=\"greek\">οἴκου</span> <span class=\"greek\">προστῆναι</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">οἶδεν</span>, não sabe administrar a própria casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:5</a>. <span class=\"greek\">εἰδὼς</span> <span class=\"greek\">καλὸν</span> <span class=\"greek\">ποιεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:17</a>. <span class=\"greek\">οἶδεν</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">εὐσεβεῖς</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">πειρασμοῦ</span> <span class=\"greek\">ῥύεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:9</a>. <span class=\"greek\">οἴδασιν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">κόπου</span> … <span class=\"greek\">πορίζειν</span> <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τροφήν</span> 10:4. <span class=\"greek\">εἰδὼς</span> <span class=\"greek\">φέρειν</span> <span class=\"greek\">μαλακίαν</span>, aquele que sabia suportar a dor 1 Cl 16:3 (Is 53:3).—Uso absoluto: <span class=\"greek\">ἀσφαλίσασθε</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">οἴδατε</span>, tornai-o (= o túmulo) tão seguro quanto puderdes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.65\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:65</a>.</p><p class=\"entry-text\">④ Apreender o significado de algo, entender, reconhecer, chegar a saber, experimentar (Just., D. 114, 1 <span class=\"greek\">ἣν</span> <span class=\"greek\">τέχνην</span> <span class=\"greek\">ἐὰν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">εἰδῶσιν</span> [sobre alegorização]; Sallust. 3 p. 4, 8 <span class=\"greek\">τοῖς</span> <span class=\"greek\">δυναμένοις</span> <span class=\"greek\">εἰδέναι</span> = àqueles capazes de entendê-lo), com acusativo de coisa: <span class=\"greek\">τὴν</span> <span class=\"greek\">παραβολήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:13</a>. <span class=\"greek\">τὸν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πυροῦ</span> <span class=\"greek\">σπόρον</span> … <span class=\"greek\">ὅτι</span>, a semeadura de trigo … que AcPlCor 2:26. <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀνθρώπου</span>, entender o que é verdadeiramente humano <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:11</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">χαρισθέντα</span> <span class=\"greek\">ἡμῖν</span>, versículo 12. <span class=\"greek\">τὰ</span> <span class=\"greek\">συνέχοντά</span> <span class=\"greek\">με</span> IRo 6:3. Com interrogativa indireta subsequente: <span class=\"greek\">εἰδέναι</span> <span class=\"greek\">τίς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐλπίς</span>, chegar a saber qual é a esperança <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:18</a>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">οἶδα</span> <span class=\"greek\">τί</span> <span class=\"greek\">λέγεις</span>, não entendo o que queres dizer (Philostrat., Vi. Soph. 1, 7, 4; TestAbr A 16, p. 98, 10 [Stone p. 44] <span class=\"greek\">οἶδα</span> <span class=\"greek\">τί</span> <span class=\"greek\">λέγεις</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.70\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:70</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:16</a>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.60\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:60</a> (Oenomaus em Eus., PE 6, 7, 9 <span class=\"greek\">οὐκ</span> <span class=\"greek\">οἶσθα</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">λέγεις</span>; Just., D. 9, 1 <span class=\"greek\">οὐ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">οἶδας</span> <span class=\"greek\">ὅ</span> <span class=\"greek\">λέγεις</span>). <span class=\"greek\">εἴσεσθε</span> <span class=\"greek\">ὅσα</span> <span class=\"greek\">παρέχει</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>, experimentareis aquilo que Deus concede Dg 12:1.—Especialmente sobre a capacidade de Jesus de perscrutar pensamentos das pessoas: <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐνθυμήσεις</span> <span class=\"greek\">αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:25</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ὑπόκρισιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:15</a>. <span class=\"greek\">τοὺς</span> <span class=\"greek\">διαλογισμοὺς</span> <span class=\"greek\">αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:8</a>; cf. 11:17. PEg2 50 (=ASyn. 280, 45). Acrescenta-se <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτῷ</span>, seguido de <span class=\"greek\">ὅτι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.61\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:61</a>.</p><p class=\"entry-text\">⑤ Lembrar-se, recordar, trazer à memória, ter consciência de: <span class=\"greek\">λοιπὸν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">οἶδα</span> <span class=\"greek\">εἴ</span> <span class=\"greek\">τινα</span> <span class=\"greek\">ἄλλον</span> <span class=\"greek\">ἐβάπτισα</span>, não me lembro de ter batizado mais ninguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:16</a> (cf. Lucian, Dial. Meretr. 1, 1 <span class=\"greek\">οἶσθα</span> <span class=\"greek\">αὐτόν</span>, <span class=\"greek\">ἢ</span> <span class=\"greek\">ἐπιλέλησαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄνθρωπον</span>; <span class=\"greek\">οὐκ</span>, <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">οἶδα</span>, <span class=\"greek\">ὦ</span> <span class=\"greek\">Γλυκέριον</span>; Field, Notes 187).</p><p class=\"entry-text\">⑥ Reconhecer mérito, respeitar, honrar: <span class=\"greek\">εἰδέναι</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">κοπιῶντας</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span>, respeitar os que trabalham entre vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:12</a> (<span class=\"greek\">εἰδέναι</span> <span class=\"greek\">τινά</span> pode significar reconhecer ou honrar alguém [Ael. Aristid. 35, 35 K.=9 p. 111 D. <span class=\"greek\">τοὺς</span> <span class=\"greek\">κρείττους</span> <span class=\"greek\">εἰδέναι</span>], mas também pode significar interessar-se por alguém, cuidar de alguém: Witkowski 30, 7 <span class=\"greek\">οἱ</span> <span class=\"greek\">θεοί</span> <span class=\"greek\">σε</span> <span class=\"greek\">οἴδασιν</span>). <span class=\"greek\">θεὸν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπίσκοπον</span> <span class=\"greek\">εἰδέναι</span>, honrar Deus e o bispo ISm 9:1.—<span class=\"greek\">τοῦτο</span> <span class=\"greek\">ἴστε</span> <span class=\"greek\">γινώσκοντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:5</a> foi considerado hebraísmo (assim ARobinson 1904 ad loc., chamando atenção para LXX 1 Km 20:3 <span class=\"greek\">γινώσκων</span> <span class=\"greek\">οἶδεν</span> e Sym. Jer 49 [42]: 22 <span class=\"greek\">ἴστε</span> <span class=\"greek\">γινώσκοντες</span>), mas, contra tal interpretação, SPorter, ZNW 81, ’90, 270–76.—B. 1209. DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0250-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκεῖος, (α,) ον</h1><div class=\"entry-meta\"><span>adjetivo substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκεῖος</span>, (<span class=\"greek\">α</span>,) <span class=\"greek\">ον</span> (<span class=\"greek\">οἶκος</span>; Hes., Hdt. e posteriores), literalmente «pertencente à casa»; em nossa literatura apenas como substantivo <span class=\"greek\">οἱ</span> <span class=\"greek\">οἰκ</span>., pessoas ligadas por parentesco ou circunstâncias, formando grupo estreitamente unido, membros de uma casa.</p><p class=\"entry-text\">ⓐ Com ênfase nos vínculos familiares normais ou na associação por causa comum (Jos., Vi. 183), acerca de todos os membros de uma casa MPol 6:2. <span class=\"greek\">οἱ</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σπέρματός</span> <span class=\"greek\">σου</span>, os teus parentes de sangue 3:3 (Is 58:7). Com <span class=\"greek\">ἴδιοι</span>, membros da própria família (escólio sobre Pla. 20e <span class=\"greek\">λέγονται</span> <span class=\"greek\">οἰκεῖοι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">συγγενεῖς</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:8</a> (Diod S 5, 18, 1; Appian, Hann. 28 §118; SIG 317, 38; 560, 21; 591, 59 <span class=\"greek\">φίλοι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἰκεῖοι</span>; TestReub 3:5 <span class=\"greek\">γένος</span> <span class=\"greek\">κ</span>. <span class=\"greek\">οἰκεῖοι</span>).</p><p class=\"entry-text\">ⓑ Com ênfase na associação por causa comum ou crença (com <span class=\"greek\">συμπολῖται</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁγίων</span>): <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, membros da casa de Deus (cf. Marinus, Vi. Procli 32 <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοφιλοῦς</span> <span class=\"greek\">ἀνδρὸς</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεὸν</span> <span class=\"greek\">οἰκειότης</span>), acerca dos cristãos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:19</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span>, aqueles que pertencem à família da fé <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:10</a> (cf. Polyb. 5, 87, 3 <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡσυχίας</span>; 4, 57, 4; 14, 9, 5; Diod S 13, 91, 4; 19, 70, 3 <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τυραννίδος</span>; Strabo 17, 1, 5 <span class=\"greek\">οἰκ</span>. <span class=\"greek\">σοφίας</span>.—GWhitaker, Exp. 8ª série 23, 1921, 76ff).—Ver <span class=\"greek\">ἑταῖρος</span>.—DELG s.v. <span class=\"greek\">οἶκος</span> B. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0250-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκετεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκετεία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (cf. <span class=\"greek\">οἰκέτης</span>; desde SIG 495, 112f [c. 230 b.c.]; Strabo 14, 5, 2; Lucian, De Merc. Cond. 15; Epict., Ench. 33, 7 [ver Schenkl, aparato]; SIG 694, 54f; 695, 61; PTebt 285, 6; Sym. Job 1:3; EpArist 14; 15; Jos., Ant. 12, 30), conjunto dos membros escravizados de uma casa, escravos domésticos: <span class=\"greek\">καταστῆσαί</span> <span class=\"greek\">τινα</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκετείας</span> <span class=\"greek\">αὐτοῦ</span>, encarregar alguém (dos escravos) de sua casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:45</a> (variantes de leitura <span class=\"greek\">οἰκίας</span>, <span class=\"greek\">θεραπείας</span>).—DELG s.v. <span class=\"greek\">οἶκο</span> A II 4. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0250-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκέτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκέτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (de <span class=\"greek\">οἶκος</span>, cf. verbete precedente), literalmente «membro da casa», depois especificamente escravo doméstico, criado, e escravo em geral (no sentido específico Aeschyl., Hdt. e posteriores) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:7</a>. Em oposição a <span class=\"greek\">δεσπότης</span> (Dio Chrys. 64 [14], 10; Ael. Aristid. 45 p. 40 D.; Pr 22:7; Philo, Deus Imm. 64) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:18</a>; em oposição a <span class=\"greek\">κύριος</span>, como senhor (Philo, Poster. Cai. 138) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:13</a>; 2 Cl 6:1. <span class=\"greek\">ἀλλότριος</span> <span class=\"greek\">οἰκ</span>., escravo de outro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:4</a>.—B. 1332. DELG s.v. <span class=\"greek\">οἶκο</span> A II 4. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0250-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκέω</span> (<span class=\"greek\">οἶκος</span>), futuro <span class=\"greek\">οἰκήσω</span>; aoristo <span class=\"greek\">ᾤκησα</span> LXX.</p><p class=\"entry-text\">① Residir em lugar, viver, morar, habitar, intransitivo (Hom. e posteriores; inscrições, papiros, LXX; pseudoepígrafos; Philo, Aet. M. 148 [<span class=\"greek\">ἐν</span>]; Just., D. 78, 9 [<span class=\"greek\">ἐν</span>]; PJena col. 4, 20; Did.): <span class=\"greek\">οἰκ</span>. <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span>, morar com alguém (M. Ant. 1, 17, 15; Gen 24:3; 27:44) Hv 5:2; no matrimônio (Soph., Oed. R. 990) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:12</a>f. <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, em alguém ou em alguma coisa (PPetr II, 17 [3], 4 [III b.c.] <span class=\"greek\">οἴκημα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">οἰκοῦμεν</span>; Sb 6762, 1; PRev 29, 6): acerca dos cristãos <span class=\"greek\">ἐν</span> <span class=\"greek\">κόσμῳ</span> <span class=\"greek\">οἰκ</span>. Dg 6:3b. Também sobre a alma <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σώματι</span>, ibidem a. Do Espírito de Deus que habita numa pessoa (cf. TestGad 5:4 <span class=\"greek\">ὁ</span> <span class=\"greek\">φόβος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">οἰκεῖ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span>; Just., A I, 32, 8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:9</a>, 11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:16</a>. Do bem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:18</a>. Do pecado versículos 17 e 20.</p><p class=\"entry-text\">② Habitar lugar, residir em, ocupar, transitivo, com <span class=\"greek\">τὶ</span>, alguma coisa, literalmente (Mitt-Wilck II/2, 284, 5 <span class=\"greek\">οἰκίαν</span> [TestJob 44:1]; PGiss 2, 23; PTebt 104, 21; Gen 24:13; Philo, Conf. Lingu. 106 <span class=\"greek\">κόσμον</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">πατρίδα</span> <span class=\"greek\">οἰκ</span>.; Jos., Ant. 14, 88, C. Ap. 1, 9; Orig., C. Cels. <span class=\"greek\">τὴν</span> <span class=\"greek\">Ἀσίαν</span> … <span class=\"greek\">οἰκ</span>.; Iren. 1, 10, 2 [Harv. I 92, 3]) <span class=\"greek\">πατρίδας</span> <span class=\"greek\">ἰδίας</span> Dg 5:5. Em sentido transcendente, acerca de Deus: <span class=\"greek\">φῶς</span> <span class=\"greek\">οἰκῶν</span> <span class=\"greek\">ἀπρόσιτον</span>, aquele que habita em luz inacessível <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:16</a>.—Sobre <span class=\"greek\">οἰκουμένη</span>, ver verbete próprio.—DELG s.v. <span class=\"greek\">οἶκο</span> C. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0250-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἴκημα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἴκημα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">οἰκέω</span>; Pind., Hdt. e posteriores; inscrições, papiros, LXX; TestAbr A 4 p. 80, 21, 29f [Stone p. 8]; Philo, Vi. Cont. 25; Joseph.).</p><p class=\"entry-text\">① Cômodo individual numa habitação, quarto, aposento (Hdt. 1, 9; 10; Menand., Sam. 19; Diod S 1, 92, 6; Appian, Bell. Civ. 4, 24 §98; Jos., Ant. 8, 134; 137; 14, 455; TestAbr A): <span class=\"greek\">οἰκήματα</span> <span class=\"greek\">μάταια</span>, aposentos que passarão Hs 1:1.</p><p class=\"entry-text\">② Cômodo num complexo prisional ou moradia separada usada para detenção, aposento de custódia, cela (Thu. 4, 47, 3 e 4, 48, 1, acerca de prédio amplo usado para detenção temporária; Demosth. 32, 29, empregado eufemisticamente para cela; Lucian, Tox. 29, acerca de aposentos abafados numa prisão; Plut., Agis 803–4 [19, 5; 8; 9]; Aelian, VH 6, 1): <span class=\"greek\">φῶς</span> <span class=\"greek\">ἔλαμψεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">οἰκ</span>., uma luz brilhou na cela (de Pedro) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:7</a>; esse uso não é necessariamente eufemístico (contrariamente a Haenchen ad loc.), pois se trata de um quarto ou cela num complexo maior de detenção chamado <span class=\"greek\">φυλακή</span> (versículo 6); aparentemente, a luz ilumina somente o espaço de Pedro.—DELG s.v. <span class=\"greek\">οἶκο</span> C. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0250-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἴκησις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἴκησις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">οἰκέω</span>), casa, residência, habitação (assim em Aeschyl., Hdt. e posteriores; Diod S 1, 50, 6; 17, 105, 5; SIG 1216, 11; PMagd 29, 3 [III b.c.]; BGU 1113, 19; PTebt 489; Jdth 7:14; 1 Macc 13:48; ViJer 2 [p. 71, 5 Sch.]; Philo; Jos., Vi. 159, Ant. 14, 261; Just., D. 139, 2 [«morada»]) Hs 1:4.—DELG s.v. <span class=\"greek\">οἶκο</span> C.</p></section></article>\n"};
